import React, { useState, useEffect } from "react";
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import "./ManageTeachers.css";

const AdminManageTeachers = () => {
  const [students, setTeachers] = useState([]);
  const [form, setForm] = useState({
    name: "",
    email: "",
    username: "",
    password: "",
    subject: "",
  });
  const [editId, setEditId] = useState(null);

  const TeachersCollectionRef = collection(db, "teachers");

  // Fetch students from Firestore
  const fetchStudents = async () => {
    const data = await getDocs(TeachersCollectionRef);
    setTeachers(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const addOrUpdateTeacher = async (e) => {
    e.preventDefault();
    if (editId) {
      const teacherDoc = doc(db, "teacher", editId);
      await updateDoc(teacherDoc, form);
    } else {
      await addDoc(teachersCollectionRef, form);
    }
    fetchTeachers();
    setForm({ name: "", email: "", username: "", password: "", subject: "" });
    setEditId(null);
  };

  const deleteTeacher = async (id) => {
    const teacherDoc = doc(db, "teachers", id);
    await deleteDoc(teacherDoc);
    fetchTeachers();
  };

  const editTeacher = (teacher) => {
    setForm(teacher);
    setEditId(teacher.id);
  };

  return (
    <div className="manage-students-container">
      <h2>Manage Teachers</h2>
      <form onSubmit={addOrUpdateStudent} className="student-form">
        <label htmlFor="name">Name:</label>
        <input
          type="text"
          id="name"
          name="name"
          value={form.name}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="email">Email:</label>
        <input
          type="email"
          id="email"
          name="email"
          value={form.email}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="username">Username:</label>
        <input
          type="text"
          id="username"
          name="username"
          value={form.username}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="password">Password:</label>
        <input
          type="password"
          id="password"
          name="password"
          value={form.password}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="teacherSubject">Subjects:</label>
        <select
          id="teacherSubject"
          name="teacherSubject"
          value={form.teacherSubject}
          onChange={handleInputChange}
          required
        >
          <option value="" disabled>
            Select Class
          </option>
          <option value="Primary 1">Primary 1</option>
          <option value="Primary 2">Primary 2</option>
          <option value="Primary 3">Primary 3</option>
          <option value="Primary 4">Primary 4</option>
          <option value="Primary 5">Primary 5</option>
          <option value="Primary 6">Primary 6</option>
          <option value="JSS 1">JSS 1</option>
          <option value="JSS 2">JSS 2</option>
          <option value="JSS 3">JSS 3</option>
          <option value="SSS 1">SSS 1</option>
          <option value="SSS 2">SSS 2</option>
          <option value="SSS 3">SSS 3</option>
        </select>

        <button type="submit" className="form-btn">
          {editId ? "Update Teacher" : "Add Teacher"}
        </button>
      </form>
      <table className="students-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Username</th>
            <th>Subject</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {teachers.map((teacher) => (
            <tr key={teacher.id}>
              <td>{teacher.name}</td>
              <td>{teacher.email}</td>
              <td>{teacher.username}</td>
              <td>{teacher.teacherSubject}</td>
              <td>
                <button onClick={() => editStudent(teacher)} className="edit-btn">
                  Edit
                </button>
                <button onClick={() => deleteTeacher(teacher.id)} className="delete-btn">
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default AdminManageTeachers;
